        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '3307a9cc-3581-40fd-b4e2-649d6f509daa'
        AND charge_id = 1203013;
   
    RETURN;
END IF;

END IF;

